package io.busystack.busydata.metadata;

import io.busystack.busydata.protocol.*;
import java.util.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class MetadataNamesTest {
    private static final MetadataScope TABLES=new MetadataScope("db","public","",ObjectKind.TABLE);
    private static final IdentifierRules RULES=new IdentifierRules(Engine.POSTGRESQL,0);
    private static SchemaObject wire(String name,String id){return SchemaObject.newBuilder().setCatalog("db").setSchema("public").setName(name).setKind(ObjectKind.TABLE).setSubtype(ObjectSubtype.ORDINARY_TABLE).putProperties("nativeId",id).putProperties("nativeGeneration",id+":42").putProperties("catalogFingerprint","catalog-"+name).putProperties("typeDependenciesFingerprint","types-"+name).build();}
    private static MetadataObject object(SchemaObject wire,IntrospectionLevel level){return MetadataObject.from("source","profile","",RULES,wire,level,1,1);}
    private static MetadataSnapshot snapshot(){
        var relation=object(wire("kept","11").toBuilder().setDefinition("CREATE TABLE kept (n NUMERIC DEFAULT 123.456)").putProperties("unabridged","retained-source-fact").build(),IntrospectionLevel.SOURCE);
        var column=object(SchemaObject.newBuilder().setCatalog("db").setSchema("public").setTable("kept").setName("n").setKind(ObjectKind.COLUMN).putProperties("nativeId","11:1").putProperties("default","123.456").build(),IntrospectionLevel.STRUCTURE);
        var foreign=object(SchemaObject.newBuilder().setCatalog("db").setSchema("public").setTable("child").setName("points_to_kept").setKind(ObjectKind.FOREIGN_KEY).putProperties("relationshipVerified","true").putProperties("referencedCatalog","db").putProperties("referencedSchema","public").putProperties("referencedTable","kept").build(),IntrospectionLevel.STRUCTURE);
        var coverage=new HashMap<MetadataScope,MetadataCoverage>();
        coverage.put(TABLES,new MetadataCoverage(TABLES,IntrospectionLevel.SOURCE,MetadataState.STALE,false,"old-names",1,1,123,"An acknowledged DDL changed names"));
        for(ObjectKind kind:MetadataNames.CHILDREN){var scope=new MetadataScope("db","public","kept",kind);coverage.put(scope,new MetadataCoverage(scope,IntrospectionLevel.STRUCTURE,MetadataState.AVAILABLE,true,kind==ObjectKind.COLUMN?"1:42":"0:0",1,1,123,""));}
        for(ObjectKind kind:List.of(ObjectKind.CONSTRAINT,ObjectKind.FOREIGN_KEY)){var scope=new MetadataScope("db","public","child",kind);coverage.put(scope,new MetadataCoverage(scope,IntrospectionLevel.STRUCTURE,MetadataState.AVAILABLE,true,"1:99",1,1,123,""));}
        return new MetadataSnapshot("source","profile",7,1,123,RULES,List.of(relation,column,foreign),coverage);
    }
    private static MetadataNames.Evidence evidence(){var values=new EnumMap<ObjectKind,Map<String,String>>(ObjectKind.class);for(ObjectKind kind:MetadataNames.CHILDREN)values.put(kind,kind==ObjectKind.COLUMN?Map.of("kept","1:42"):Map.of());return new MetadataNames.Evidence(values,Map.of("kept","types-kept"));}
    private static MetadataNames.Reconciled reconcile(MetadataSnapshot before,MetadataScope scope,List<MetadataObject> acquired,MetadataNames.Evidence evidence)throws Exception{return MetadataNames.reconcile(before,scope,acquired,evidence,Long.MAX_VALUE);}
    @Test void verifiedNamesKeepTheSameHigherLevelObjectWithoutCopyingSource()throws Exception{var before=snapshot();var result=reconcile(before,TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),evidence());assertSame(before.resolve("db","public",ObjectKind.TABLE,"","kept",true).getFirst(),result.objects().getFirst());assertEquals(IntrospectionLevel.SOURCE,result.objects().getFirst().level());assertTrue(result.staleScopes().isEmpty());assertFalse(result.objects().getFirst().source().isEmpty());}
    @Test void externalCatalogChangeRetainsFactsButMarksTheirAvailabilityStale()throws Exception{var before=snapshot();var names=object(wire("kept","11").toBuilder().putProperties("catalogFingerprint","changed").build(),IntrospectionLevel.NAMES);var result=reconcile(before,TABLES,List.of(names),evidence());assertEquals(MetadataState.STALE,result.objects().getFirst().state());assertEquals("retained-source-fact",result.objects().getFirst().properties().get("unabridged"));assertEquals(before.resolve("db","public",ObjectKind.TABLE,"","kept",true).getFirst().source(),result.objects().getFirst().source());assertTrue(result.staleScopes().contains(new MetadataScope("db","public","kept",ObjectKind.COLUMN)));assertTrue(result.staleScopes().contains(new MetadataScope("db","public","child",ObjectKind.FOREIGN_KEY)));assertTrue(result.staleScopes().contains(new MetadataScope("db","public","child",ObjectKind.CONSTRAINT)));}
    @Test void deletedAndRecreatedNamesNeverInheritTheOldNativeColumnFacts()throws Exception{var before=snapshot();var result=reconcile(before,TABLES,List.of(object(wire("kept","999"),IntrospectionLevel.NAMES)),evidence());assertEquals(IntrospectionLevel.NAMES,result.objects().getFirst().level());assertNotEquals(before.resolve("db","public",ObjectKind.TABLE,"","kept",true).getFirst().identity(),result.objects().getFirst().identity());assertTrue(result.staleScopes().contains(new MetadataScope("db","public","kept",ObjectKind.COLUMN)));}
    @Test void anUnchangedNameCannotHideChangedColumnsOrTypeDependencies()throws Exception{var before=snapshot();var changed=new EnumMap<ObjectKind,Map<String,String>>(ObjectKind.class);changed.putAll(evidence().children());changed.put(ObjectKind.COLUMN,Map.of("kept","2:43"));assertEquals(MetadataState.STALE,reconcile(before,TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),new MetadataNames.Evidence(changed,evidence().typeDependencies())).objects().getFirst().state());assertEquals(MetadataState.STALE,reconcile(before,TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),new MetadataNames.Evidence(evidence().children(),Map.of("kept","types-changed"))).objects().getFirst().state());}
    @Test void deletedRelationInvalidatesItsChildrenAndIncomingRelationshipOwners()throws Exception{var result=reconcile(snapshot(),TABLES,List.of(),evidence());assertTrue(result.objects().isEmpty());assertTrue(result.staleScopes().contains(new MetadataScope("db","public","kept",ObjectKind.COLUMN)));assertTrue(result.staleScopes().contains(new MetadataScope("db","public","child",ObjectKind.FOREIGN_KEY)));}
    @Test void aNativeRenameKeepsTheNewNameWhileOldSourceAndChildrenRemainExplicitlyStale()throws Exception{var before=snapshot();var renamed=object(wire("renamed","11"),IntrospectionLevel.NAMES);var result=reconcile(before,TABLES,List.of(renamed),evidence());assertEquals("renamed",result.objects().getFirst().identity().name());assertEquals("renamed",result.objects().getFirst().displayName());assertEquals(before.resolve("db","public",ObjectKind.TABLE,"","kept",true).getFirst().identity().key(),result.objects().getFirst().identity().key());assertEquals(MetadataState.STALE,result.objects().getFirst().state());assertTrue(result.staleScopes().contains(new MetadataScope("db","public","kept",ObjectKind.COLUMN)));}
    @Test void missingNativeEvidenceDoesNotBecomeACompleteEmptyFingerprint()throws Exception{var before=snapshot();var result=reconcile(before,TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),new MetadataNames.Evidence(Map.of(),evidence().typeDependencies()));assertEquals(MetadataState.STALE,result.objects().getFirst().state());}
    @Test void reconciliationHasTheOriginalHardDeadline(){assertThrows(java.util.concurrent.TimeoutException.class,()->MetadataNames.reconcile(snapshot(),TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),evidence(),System.nanoTime()-1));}
    @Test void supersededReconciliationCancelsBeforeCopyingFacts()throws Exception{var context=io.grpc.Context.current().withCancellation();context.cancel(new java.util.concurrent.CancellationException("Superseded"));assertThrows(java.util.concurrent.CancellationException.class,()->context.call(()->reconcile(snapshot(),TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),evidence())));}
    private static MetadataSnapshot filtered(boolean source){var original=snapshot();var known=original.resolve("db","public",ObjectKind.TABLE,"","kept",true).getFirst();var entries=new ArrayList<MetadataObject>();for(var object:original.identities().values())if(object.identity().kind()==ObjectKind.TABLE||object.identity().kind()==ObjectKind.COLUMN)entries.add(object==known&&!source?new MetadataObject(known.identity(),known.displayName(),known.quotedIdentifier(),known.lookupKey(),known.properties(),"",IntrospectionLevel.STRUCTURE,MetadataState.AVAILABLE,known.sourceRevision(),known.contextRevision()):object);var coverage=new HashMap<MetadataScope,MetadataCoverage>();coverage.put(TABLES,original.coverage().get(TABLES));var columns=new MetadataScope("db","public","kept",ObjectKind.COLUMN);coverage.put(columns,original.coverage().get(columns));return new MetadataSnapshot("source","profile",8,2,124,RULES,entries,coverage);}
    @Test void excludedKindsDoNotInvalidateVerifiedRequestedColumns()throws Exception{var before=filtered(false);var proof=new MetadataNames.Evidence(Map.of(ObjectKind.COLUMN,Map.of("kept","1:42")),Map.of("kept","types-kept"),Set.of(ObjectKind.COLUMN));var result=reconcile(before,TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),proof);assertSame(before.resolve("db","public",ObjectKind.TABLE,"","kept",true).getFirst(),result.objects().getFirst());assertTrue(result.staleScopes().isEmpty());}
    @Test void missingRequestedColumnEvidenceStillInvalidates()throws Exception{var result=reconcile(filtered(false),TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),new MetadataNames.Evidence(Map.of(),Map.of("kept","types-kept"),Set.of(ObjectKind.COLUMN)));assertEquals(MetadataState.STALE,result.objects().getFirst().state());assertTrue(result.staleScopes().contains(new MetadataScope("db","public","kept",ObjectKind.COLUMN)));}
    @Test void excludedStructureCannotBlessUnverifiedSource()throws Exception{var before=filtered(true);var result=reconcile(before,TABLES,List.of(object(wire("kept","11"),IntrospectionLevel.NAMES)),new MetadataNames.Evidence(Map.of(ObjectKind.COLUMN,Map.of("kept","1:42")),Map.of("kept","types-kept"),Set.of(ObjectKind.COLUMN)));var known=before.resolve("db","public",ObjectKind.TABLE,"","kept",true).getFirst();assertEquals(MetadataState.AVAILABLE,result.objects().getFirst().state());assertEquals(IntrospectionLevel.STRUCTURE,result.objects().getFirst().level());assertEquals("STALE",result.objects().getFirst().properties().get("sourceAvailability"));assertEquals(known.source(),result.objects().getFirst().source());assertTrue(result.staleScopes().isEmpty());var exact=new MetadataScope("db","public","",ObjectKind.TABLE,"kept",true,"",ObjectSubtype.OBJECT_SUBTYPE_UNSPECIFIED);assertEquals(Set.of(exact),MetadataCoverageReconciliation.invalidated(Map.of(exact,new MetadataCoverage(exact,IntrospectionLevel.SOURCE,MetadataState.AVAILABLE,true,"source",1,1,123,"")),TABLES,List.of(known),result.objects()));}
}
